const jsonData = pm.response.json();

pm.test('Status code is 200', () => {
    pm.response.to.have.status(200);
});

pm.test('Response has accessToken', () => {
    pm.expect(jsonData).to.have.property('accessToken');
    pm.expect(jsonData.accessToken).to.be.a('string').and.not.empty;
});

pm.test('Response has refreshToken', () => {
    pm.expect(jsonData).to.have.property('refreshToken');
    pm.expect(jsonData.refreshToken).to.be.a('string').and.not.empty;
});

pm.test('accessToken is a valid JWT format', () => {
    const parts = jsonData.accessToken.split('.');
    pm.expect(parts.length).to.equal(3);
});

pm.test('refreshToken is a valid JWT format', () => {
    const parts = jsonData.refreshToken.split('.');
    pm.expect(parts.length).to.equal(3);
});

pm.test('accessToken payload contains required fields', () => {
    const payload = JSON.parse(atob(jsonData.accessToken.split('.')[1]));
    pm.expect(payload).to.have.property('id');
    pm.expect(payload).to.have.property('username');
    pm.expect(payload).to.have.property('exp');
});

pm.test('accessToken is not expired', () => {
    const payload = JSON.parse(atob(jsonData.accessToken.split('.')[1]));
    const currentTime = Math.floor(Date.now() / 1000);
    pm.expect(payload.exp).to.be.above(currentTime);
});

